String _cstr(Pointer<Utf8> p, ThroneFFI ffi) {
  if (p == nullptr) return '';
  final s = p.toDartString();
  ffi.throne_free(p);
  return s;
}

void _checkErr(ThroneFFI ffi) {
  final p = ffi.throne_last_error();
  if (p == nullptr) return;
  final msg = p.toDartString();
  ffi.throne_free(p);
  if (msg.isNotEmpty) throw StateError(msg);
}

extension _BytesMalloc on Uint8List {
  Pointer<Uint8> mallocUint8() {
    final p = malloc<Uint8>(length);
    p.asTypedList(length).setAll(0, this);
    return p;
  }
}

/// Finalizer token: holds the FFI view, never the wrapper being collected.
class _HandleRef {
  _HandleRef(this.ffi, this.handle);
  final ThroneFFI ffi;
  final int handle;
}

/// Shared fallback for wrappers a caller forgot to release explicitly.
final Finalizer<_HandleRef> _handleFinalizer = Finalizer<_HandleRef>((ref) {
  ref.ffi.throne_handle_release(ref.handle);
});

/// Explicit, deterministic release. Prefer this over waiting for GC.
void detachHandle(Object wrapper, ThroneFFI ffi, int handle) {
  _handleFinalizer.detach(wrapper);
  ffi.throne_handle_release(handle);
}

/// All status fields in one crossing; creates no handle on the Go side.
Map<String, int>? throneStatusSnapshot(ThroneFFI ffi, int handle) {
  final p = ffi.throne_status_snapshot(handle);
  if (p == nullptr) return null;
  final s = p.toDartString();
  ffi.throne_free(p);
  if (s.isEmpty) return null;
  try {
    final v = json.decode(s) as Map<String, dynamic>;
    return v.map((k, value) => MapEntry(k, (value as num).toInt()));
  } catch (_) {
    return null;
  }
}

/// The message of the last failed crossing, or an empty string.
///
/// The Go side hands the message out once and clears it, so a call that is not
/// going to throw (the heartbeat) can still put a reason on its event without
/// leaving the text behind for the next typed call to mistake for its own.
String throneLastError(ThroneFFI ffi) {
  final p = ffi.throne_last_error();
  if (p == nullptr) return '';
  try {
    return p.toDartString();
  } finally {
    ffi.throne_free(p);
  }
}

/// Handle-table counters for FFI lifetime regression tests.
Map<String, int>? throneHandleStats(ThroneFFI ffi) {
  final p = ffi.throne_handle_stats();
  if (p == nullptr) return null;
  final s = p.toDartString();
  ffi.throne_free(p);
  if (s.isEmpty) return null;
  try {
    final v = json.decode(s) as Map<String, dynamic>;
    return v.map((k, value) => MapEntry(k, (value as num).toInt()));
  } catch (_) {
    return null;
  }
}

