// Parse one JSON event posted by the Go side (sendEvent/postTo).
Map<String, dynamic>? decodeBridgeEvent(Object? raw) {
  if (raw is! String) return null;
  try {
    final v = json.decode(raw);
    return v is Map<String, dynamic> ? v : null;
  } catch (_) {
    return null;
  }
}

